function tr(key){ return i18n[state.lang][key] || key; }

function clone(value){ return JSON.parse(JSON.stringify(value)); }

function loadData(){
  const raw = localStorage.getItem('school_org_data');
  if(!raw) return clone(DEFAULT_DATA);
  try{
    const parsed = JSON.parse(raw);
    const loaded = {...clone(DEFAULT_DATA), ...parsed};
    if(!Array.isArray(loaded.students)) loaded.students = clone(DEFAULT_DATA.students);
    if(!Array.isArray(loaded.teachers)) loaded.teachers = clone(DEFAULT_DATA.teachers);
    if(!Array.isArray(loaded.assistants)) loaded.assistants = clone(DEFAULT_DATA.assistants);
    if(!Array.isArray(loaded.activities)) loaded.activities = [];
    if(!Array.isArray(loaded.ratings)) loaded.ratings = [];
    if(!Array.isArray(loaded.complaints)) loaded.complaints = [];
    if(!Array.isArray(loaded.messages)) loaded.messages = [];
    if(!loaded.profilePhotos || typeof loaded.profilePhotos !== 'object') loaded.profilePhotos = {};
    return loaded;
  }catch(e){ return clone(DEFAULT_DATA); }
}

const data = loadData();

// إضافة البيانات المزروعة (مشاريع، بحوث، فعاليات، طلاب، مشرفين) إذا لم تكن موجودة
['students','teachers','activities'].forEach(key=>{
  DEFAULT_DATA[key].forEach(seed=>{
    const found=data[key].find(x=>x.id===seed.id);
    if(!found) data[key].push(clone(seed));
    else if(key!=='activities') found.identity=seed.identity;
  });
});
saveData();

function saveData(){
  localStorage.setItem('school_org_data', JSON.stringify(data));
}

function saveState(){
  localStorage.setItem(STORAGE_KEY, JSON.stringify({
    lang:state.lang,theme:state.theme,user:state.user,page:state.page,roleView:state.roleView
  }));
}

function restoreState(){
  try{
    const raw = localStorage.getItem(STORAGE_KEY);
    if(!raw) return;
    const saved = JSON.parse(raw);
    if(saved && saved.user){
      state.user = saved.user;
      state.page = saved.page || 'home';
      state.roleView = saved.roleView || 'home';
    }
  }catch(e){}
}

function applyTheme(){
  document.documentElement.setAttribute('data-theme',state.theme);
  document.documentElement.lang = state.lang;
  document.documentElement.dir = state.lang === 'ar' ? 'rtl' : 'ltr';
  localStorage.setItem('lang',state.lang);
  localStorage.setItem('theme',state.theme);
  saveState();
}

function getRoleBadge(role){
  return role === 'student' ? tr('student') : role === 'teacher' ? tr('teacher') : role === 'assistant' ? tr('assistant') : tr('admin');
}

function getRoleSection(role){
  return role === 'student' ? tr('studentSection') : role === 'teacher' ? tr('teacherSection') : role === 'assistant' ? tr('assistantSection') : tr('adminSection');
}

function getCurrentUserLabel(){
  return state.user?.name || state.user?.identity || tr('brand');
}

function renderAvatar(user,className){
  if(user?.avatar) return `<img class="${className}" src="${user.avatar}" alt="">`;
  return `<div class="${className}">${(getCurrentUserLabel().charAt(0)||'م').toUpperCase()}</div>`;
}

function readImageFile(file){
  if(!file || !file.size) return Promise.resolve('');
  return new Promise((resolve,reject)=>{
    const reader = new FileReader();
    reader.onerror=()=>reject(new Error('Unable to read image'));
    reader.onload=()=>{
      const image = new Image();
      image.onerror=()=>reject(new Error('Invalid image'));
      image.onload=()=>{
        const scale=Math.min(1,1000/Math.max(image.width,image.height));
        const canvas=document.createElement('canvas');
        canvas.width=Math.max(1,Math.round(image.width*scale));
        canvas.height=Math.max(1,Math.round(image.height*scale));
        canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
        resolve(canvas.toDataURL('image/jpeg',.82));
      };
      image.src=reader.result;
    };
    reader.readAsDataURL(file);
  });
}

function getNotificationsCount(){
  if(!state.user) return 0;
  return data.messages.filter(m=>m.to===state.user.identity || m.to===state.user.role || m.to==='all').length;
}

function pageBreadcrumb(extra=[]){
  const segments=[{label:tr('home'),page:'landing'}];
  if(state.user) segments.push({label:getRoleSection(state.user.role),page:'home'});
  segments.push(...extra);

  const unique=[];
  segments.forEach(s=>{
    if(!unique.some(x=>x.page===s.page && x.label===s.label)) unique.push(s);
  });

  return `<nav class="breadcrumb" aria-label="breadcrumb">
    ${unique.map((s,i)=>{
      const last=i===unique.length-1;
      return last
        ? `<span class="breadcrumb-current">${s.label}</span>`
        : `<><button class="breadcrumb-link" data-action="goto-page" data-page="${s.page}">${s.label}</button><span class="breadcrumb-sep">›</span></>`;
    }).join('')}
  </nav>`;
}

