function normName(n){
  return String(n||'').replace(/[إأآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/\s+/g,' ').trim();
}

function isOwnActivity(item){
  const u=state.user;
  if(!u) return false;
  const me=normName(u.name).split(' ');
  const same=n=>{
    const w=normName(n).split(' ');
    return !!w[0]&&(w.slice(0,me.length).join(' ')===me.join(' ')||me.slice(0,w.length).join(' ')===w.join(' '));
  };
  if(u.role==='student') return String(item.student||'').split(/\s+و\s+/).filter(Boolean).some(same);
  return !!item.supervisor&&same(item.supervisor);
}

function renderReceivedRatings(item){
  const esc=t=>String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const list=data.ratings.filter(r=>r.activityId===item.id);
  const ar=state.lang==='ar';
  if(!list.length) return `<small>${ar?'لا توجد تقييمات بعد':'No ratings yet'}</small>`;
  const avg=Math.round(list.reduce((a,r)=>a+Number(r.score||0),0)/list.length*10)/10;
  return `<small><strong>★ ${ar?'المتوسط':'Average'}: ${avg} / 100 (${list.length} ${ar?'تقييم':'ratings'})</strong></small>`+
    list.map(r=>`<small>• ${esc(r.score)} / 100${r.reason?' — '+esc(r.reason):''}</small>`).join('');
}

function renderActivityList(kindKey){
  const real={ 'activity-projects':'project','activity-research':'research','activity-events':'event' }[kindKey]||kindKey;
  const items=data.activities.filter(x=>x.kind===real&&isOwnActivity(x));
  return `<div class="panel-wrap">
    ${pageBreadcrumb([{label:tr('activities'),page:'activities'},{label:kindLabel(real),page:kindKey}])}
    <h2>${kindLabel(real)}</h2>
    <div class="list-box">${items.length?items.map(item=>`<article class="list-row">
      ${renderThumbnail(item.image,item.name)}
      <div class="row-copy"><strong>${state.lang==='ar'?(item.nameAr||item.name||tr('activityName')):(item.nameEn||item.nameAr||tr('activityName'))}</strong><span>${state.lang==='ar'?(item.descriptionAr||item.description||''):(item.descriptionEn||item.descriptionAr||'')}</span><small>${item.student||''}${item.supervisor?' • '+item.supervisor:''}</small>${renderReceivedRatings(item)}</div>
    </article>`).join(''):`<div class="empty-state">${tr('noData')}</div>`}</div>
  </div>`;
}

