function renderApp(){
  applyTheme();
  document.body.classList.toggle('menu-open',state.menuOpen&&!!state.user);
  if(!state.user){
    state.page==='login'?renderLogin():renderLanding();
    return;
  }

  let inner=buildDashboard();
  const pages={
    home:buildDashboard,activities:buildActivitiesPage,ratings:buildRatingsPage,
    complaints:buildComplaintsPage,
    'add-activities':buildAddActivitiesPage,members:buildMembersPage,
    'add-members':buildAddMembersPage,'remove-members':buildRemoveMembersPage,
    contact:buildContactPage,account:buildAccountPage
  };
  if(pages[state.page]) inner=pages[state.page]();

  if(['activity-projects','activity-research','activity-events'].includes(state.roleView)) inner=renderActivityList(state.roleView);
  if(state.roleView.startsWith('rate-')) inner=buildRatingsPage();
  if(state.roleView.startsWith('new-activity-')) inner=buildAddActivitiesPage();
  if(state.roleView.startsWith('members-')) inner=buildMembersPage();
  if(state.roleView.startsWith('new-member-')) inner=buildAddMembersPage();

  app.innerHTML=layoutWrap(inner);
  bindUI();
}

function bindUI(){
  document.onkeydown=e=>{
    if(e.key==='Escape'&&state.menuOpen){state.menuOpen=false;renderApp();}
  };

  document.querySelectorAll('[data-action]').forEach(el=>{
    el.onclick=e=>{
      const d=e.currentTarget.dataset;
      handleAction(d.action,d.page||d.kind||d.person||d.target||null,d.id||null);
    };
  });

  const loginForm=document.querySelector('#login-form');
  if(loginForm) loginForm.onsubmit=e=>{
    e.preventDefault();
    const fd=new FormData(loginForm);
    const identity=String(fd.get('identity')||'').trim();
    const department=String(fd.get('department')||'').trim();
    const match=Object.values(userAccounts).find(u=>u.identity===identity&&u.department===department)||(()=>{
      const pools=[[data.students,'students1111','student'],[data.teachers,'teachers1111','teacher'],[data.assistants,'assistant1111','assistant']];
      for(const [list,dep,role] of pools){
        const m=list.find(x=>x.identity===identity);
        if(m&&dep===department) return {identity:m.identity,department:dep,role,name:m.name,gender:m.gender||'',grade:m.grade||'',age:m.age||''};
      }
      return null;
    })();
    if(!match){
      document.querySelector('#login-error').textContent=state.lang==='ar'?'بيانات الدخول غير صحيحة':'Incorrect login details';
      return;
    }
    state.user={...match,avatar:data.profilePhotos[identity]||''};
    state.page='home';state.roleView='home';state.menuOpen=false;
    saveState();renderApp();
  };

  const complaintForm=document.querySelector('#complaint-form');
  if(complaintForm) complaintForm.onsubmit=e=>{
    e.preventDefault();
    const fd=new FormData(complaintForm);
    data.complaints.push({id:String(Date.now()),by:state.user.name,title:String(fd.get('title')||''),text:String(fd.get('text')||'')});
    saveData();state.page='complaints';state.roleView='complaints';renderApp();
  };

  const activityForm=document.querySelector('#add-activity-form');
  if(activityForm) activityForm.onsubmit=async e=>{
    e.preventDefault();
    const fd=new FormData(activityForm);
    const image=await readImageFile(fd.get('image'));
    data.activities.push({
      id:String(Date.now()),kind:String(fd.get('kind')),name:String(fd.get('name')||''),
      description:String(fd.get('description')||''),student:String(fd.get('student')||''),
      supervisor:String(fd.get('supervisor')||''),image
    });
    saveData();state.page='add-activities';state.roleView='home';renderApp();
  };

  const memberForm=document.querySelector('#add-member-form');
  if(memberForm) memberForm.onsubmit=async e=>{
    e.preventDefault();
    const fd=new FormData(memberForm);
    const kind=String(fd.get('kind'));
    const name=String(fd.get('name')||'').trim();
    const identity=String(fd.get('identity')||'').trim();
    const extra=String(fd.get('extra')||'').trim();
    if(name.split(/\s+/).length<3){
      alert(state.lang==='ar'?'يجب أن يكون الاسم مكوّناً من ثلاث كلمات':'The name must contain three words');
      return;
    }
    if([...data.students,...data.teachers,...data.assistants].some(x=>x.identity===identity)){
      alert(state.lang==='ar'?'رقم الهوية مستخدم مسبقاً':'This identity number is already in use');
      return;
    }
    const image=kind==='student'?await readImageFile(fd.get('image')):'';
    const entry={id:String(Date.now()),name,identity,role:kind,grade:kind==='student'?extra:'',specialty:(kind==='teacher'||kind==='assistant')?extra:'',image};
    (kind==='student'?data.students:kind==='teacher'?data.teachers:data.assistants).push(entry);
    saveData();state.page='add-members';state.roleView='home';renderApp();
  };

  const removeForm=document.querySelector('#remove-member-form');
  if(removeForm) removeForm.onsubmit=e=>{
    e.preventDefault();
    const fd=new FormData(removeForm);
    const identity=String(fd.get('identity')||'').trim();
    const reason=String(fd.get('reason')||'').trim();
    const before=data.students.length+data.teachers.length+data.assistants.length;
    data.students=data.students.filter(x=>x.identity!==identity);
    data.teachers=data.teachers.filter(x=>x.identity!==identity);
    data.assistants=data.assistants.filter(x=>x.identity!==identity);
    if(before===data.students.length+data.teachers.length+data.assistants.length){
      alert(state.lang==='ar'?'لم يتم العثور على عضو بهذا الرقم':'No member was found with this identity number');
      return;
    }
    data.complaints.push({id:String(Date.now()),by:state.user.name,title:tr('removeMembers'),text:`${identity} - ${reason}`});
    saveData();renderApp();
  };

  document.querySelectorAll('.rating-form').forEach(form=>{
    form.onsubmit=e=>{
      e.preventDefault();
      const fd=new FormData(form);
      data.ratings.push({
        id:String(Date.now()),activityId:form.dataset.id,userId:state.user.identity,
        kind:form.dataset.kind,score:Number(fd.get('score')),reason:String(fd.get('reason')||''),
        by:state.user.name,createdAt:new Date().toISOString()
      });
      saveData();state.roleView='ratings';renderApp();
    };
  });

  const memberSearch=document.querySelector('[data-role="search-members"]');
  if(memberSearch) memberSearch.oninput=e=>{
    const value=e.target.value.toLowerCase();
    const target=state.roleView.slice(8);
    const list=target==='students'?data.students:data.teachers;
    const filtered=list.filter(p=>(p.name||'').toLowerCase().includes(value)||(p.identity||'').includes(value));
    const tbody=document.querySelector('tbody');
    if(tbody) tbody.innerHTML=memberRows(filtered,target);
  };

  const contactSearch=document.querySelector('[data-role="search-contacts"]');
  if(contactSearch) contactSearch.oninput=e=>{
    const value=e.target.value.toLowerCase();
    document.querySelectorAll('.list-box .list-row').forEach(row=>{
      row.style.display=row.textContent.toLowerCase().includes(value)?'':'none';
    });
  };

  const avatar=document.querySelector('[data-role="upload-avatar"]');
  if(avatar) avatar.onchange=async()=>{
    if(!avatar.files[0]) return;
    state.user.avatar=await readImageFile(avatar.files[0]);
    data.profilePhotos[state.user.identity]=state.user.avatar;
    saveData();saveState();renderApp();
  };
}

function handleAction(action,value,extra){
  switch(action){
    case 'switch-lang': state.lang=state.lang==='ar'?'en':'ar';renderApp();break;
    case 'toggle-theme': state.theme=state.theme==='light'?'dark':'light';renderApp();break;
    case 'go-login': state.page='login';renderApp();break;
    case 'toggle-menu': state.menuOpen=!state.menuOpen;renderApp();break;
    case 'close-menu': state.menuOpen=false;renderApp();break;
    case 'go-home': state.page='home';state.roleView='home';state.menuOpen=false;renderApp();break;
    case 'go-section': state.page='home';state.roleView='home';state.menuOpen=false;renderApp();break;
    case 'go-contact': state.page='contact';state.roleView='contact';state.menuOpen=false;renderApp();break;
    case 'go-account': state.page='account';state.roleView='account';state.menuOpen=false;renderApp();break;
    case 'go-notifications': state.page='home';state.roleView='home';state.menuOpen=false;renderApp();break;
    case 'goto-page': if(value==='landing'){state.user=null;state.page='landing';state.roleView='home';state.menuOpen=false;}else{state.page=value;state.roleView=value;} renderApp();break;
    case 'open-role-view': state.page=value;state.roleView=value;renderApp();break;
    case 'open-rating': state.page='ratings';state.roleView=`rate-${value}`;renderApp();break;
    case 'open-message-box': state.page='messages';state.roleView=`messages-${value}`;renderApp();break;
    case 'open-members': state.page='members';state.roleView=`members-${value}`;renderApp();break;
    case 'open-messaging': state.page='messages';state.roleView=`message-${value}`;renderApp();break;
    case 'open-new-member': state.page='add-members';state.roleView=`new-member-${value}`;renderApp();break;
    case 'open-new-activity': state.page='add-activities';state.roleView=`new-activity-${value}`;renderApp();break;
    case 'send-message': {
      const text=document.querySelector('#message-text')?.value.trim();
      if(text){
        const target=decodeURIComponent(value);
        data.messages.push({id:String(Date.now()),to:target,from:state.user.name,text});
        saveData();
      }
      renderApp();break;
    }
    case 'logout':
      state.user=null;state.page='landing';state.roleView='home';state.menuOpen=false;saveState();renderApp();break;
  }
}

restoreState();
renderApp();
